steps.codeExample:
import { Hono } from "hono";

const app = new Hono();

app.get("/users/:id", (c) => {
  const id = c.req.param("id");
  return c.json({ id, ativo: true }, 200);
});

app.post("/users", async (c) => {
  const body = await c.req.json();
  return c.json({ criado: body.nome }, 201);
});

